         api_check_status == CheckStatus.Busy)

  /** guarantee CHECK_BECOMES_AVAILABLE
    *   check becomes available
    * @param In_lastAdmittedToken pre-state state variable
    * @param In_lifecycleState pre-state state variable
    * @param lastAdmittedToken post-state state variable
    * @param lifecycleState post-state state variable
    * @param api_acquisition_outcome incoming data port
    * @param api_check_request incoming data port
    * @param api_publication_outcome incoming data port
    * @param api_acquisition_directive outgoing data port
    * @param api_assessment_context outgoing data port
    * @param api_check_status outgoing data port
    * @param api_publication_directive outgoing data port
    */
  @strictpure def compute_case_CHECK_BECOMES_AVAILABLE(
      In_lastAdmittedToken: Battery_Status_Assessment_Service.LastAdmittedToken.Type,
      In_lifecycleState: Battery_Status_Assessment_Service.LifecycleState.Type,
      lastAdmittedToken: Battery_Status_Assessment_Service.LastAdmittedToken.Type,
      lifecycleState: Battery_Status_Assessment_Service.LifecycleState.Type,
      api_acquisition_outcome: Battery_Status_Assessment_Service.AcquisitionOutcome.Type,
      api_check_request: Battery_Status_Assessment_Service.CheckRequest,
      api_publication_outcome: Battery_Status_Assessment_Service.PublicationOutcome.Type,
      api_acquisition_directive: Battery_Status_Assessment_Service.AcquisitionDirective.Type,
      api_assessment_context: Battery_Status_Assessment_Service.AssessmentContext.Type,
      api_check_status: Battery_Status_Assessment_Service.CheckStatus.Type,
      api_publication_directive: Battery_Status_Assessment_Service.PublicationDirective.Type): B =
    (In_lifecycleState == LifecycleState.Checking &
      api_publication_outcome != PublicationOutcome.PublicationFault &
      api_acquisition_outcome != AcquisitionOutcome.AcquisitionFault &
      api_publication_outcome != PublicationOutcome.Consumed &
      api_check_request.command != CheckCommand.Start &
      api_check_request.command != CheckCommand.Cancel &
      (In_lastAdmittedToken == CheckToken.TokenA &
        api_acquisition_outcome == AcquisitionOutcome.CapturedTokenA &
        api_publication_outcome == PublicationOutcome.OfferedTokenA |
        In_lastAdmittedToken == CheckToken.TokenB &
          api_acquisition_outcome == AcquisitionOutcome.CapturedTokenB &
          api_publication_outcome == PublicationOutcome.OfferedTokenB)) ___>:
      (lifecycleState == LifecycleState.AwaitingUse &
         lastAdmittedToken == In_lastAdmittedToken &
         api_acquisition_directive == AcquisitionDirective.NoAcquisition &
         api_assessment_context == AssessmentContext.NoContext &
         api_publication_directive == PublicationDirective.NoPublicationDirective &
         api_check_status == CheckStatus.Available)

  /** guarantee ORDINARY_NONHOLD
    *   ordinary non-hold retention
    * @param In_lastAdmittedToken pre-state state variable
    * @param In_lifecycleState pre-state state variable
    * @param lastAdmittedToken post-state state variable
    * @param lifecycleState post-state state variable
    * @param api_acquisition_outcome incoming data port
    * @param api_check_request incoming data port
    * @param api_publication_outcome incoming data port
    * @param api_acquisition_directive outgoing data port
    * @param api_assessment_context outgoing data port
    * @param api_check_status outgoing data port
    * @param api_publication_directive outgoing data port
    */
  @strictpure def compute_case_ORDINARY_NONHOLD(
      In_lastAdmittedToken: Battery_Status_Assessment_Service.LastAdmittedToken.Type,
      In_lifecycleState: Battery_Status_Assessment_Service.LifecycleState.Type,
      lastAdmittedToken: Battery_Status_Assessment_Service.LastAdmittedToken.Type,
      lifecycleState: Battery_Status_Assessment_Service.LifecycleState.Type,
      api_acquisition_outcome: Battery_Status_Assessment_Service.AcquisitionOutcome.Type,
      api_check_request: Battery_Status_Assessment_Service.CheckRequest,
      api_publication_outcome: Battery_Status_Assessment_Service.PublicationOutcome.Type,
      api_acquisition_directive: Battery_Status_Assessment_Service.AcquisitionDirective.Type,
      api_assessment_context: Battery_Status_Assessment_Service.AssessmentContext.Type,
      api_check_status: Battery_Status_Assessment_Service.CheckStatus.Type,
      api_publication_directive: Battery_Status_Assessment_Service.PublicationDirective.Type): B =
    (In_lifecycleState != LifecycleState.RecoveryHold &
      api_publication_outcome != PublicationOutcome.PublicationFault &
      api_acquisition_outcome != AcquisitionOutcome.AcquisitionFault &
      api_publication_outcome != PublicationOutcome.Consumed &
      !(api_check_request.command == CheckCommand.Cancel &
        (In_lifecycleState == LifecycleState.Checking |
          In_lifecycleState == LifecycleState.AwaitingUse)) &
      !(In_lifecycleState == LifecycleState.Idle &
        api_check_request.command == CheckCommand.Start) &
      !((In_lifecycleState == LifecycleState.Checking |
        In_lifecycleState == LifecycleState.AwaitingUse) &
        api_check_request.command == CheckCommand.Start) &
      !(In_lifecycleState == LifecycleState.Checking &
        api_check_request.command != CheckCommand.Start &
        api_check_request.command != CheckCommand.Cancel &
        (In_lastAdmittedToken == CheckToken.TokenA &
          api_acquisition_outcome == AcquisitionOutcome.CapturedTokenA &
          api_publication_outcome == PublicationOutcome.OfferedTokenA |
          In_lastAdmittedToken == CheckToken.TokenB &
            api_acquisition_outcome == AcquisitionOutcome.CapturedTokenB &
            api_publication_outcome == PublicationOutcome.OfferedTokenB))) ___>:
      (lifecycleState == In_lifecycleState &
         lastAdmittedToken == In_lastAdmittedToken &
         api_acquisition_directive == AcquisitionDirective.NoAcquisition &
         api_assessment_context == AssessmentContext.NoContext &
         api_publication_directive == PublicationDirective.NoPublicationDirective &
         (lifecycleState == LifecycleState.AwaitingUse &
           api_check_status == CheckStatus.Available |
           lifecycleState == LifecycleState.Checking &
             api_check_status == CheckStatus.Checking |
           lifecycleState == LifecycleState.Idle &
             api_check_status == CheckStatus.Idle))

  /** CEP-T-Case: Top-Level case contracts for check_lifecycle's compute entrypoint
    *
    * @param In_lastAdmittedToken pre-state state variable
    * @param In_lifecycleState pre-state state variable
    * @param lastAdmittedToken post-state state variable
    * @param lifecycleState post-state state variable
    * @param api_acquisition_outcome incoming data port
    * @param api_check_request incoming data port
    * @param api_publication_outcome incoming data port
    * @param api_acquisition_directive outgoing data port
    * @param api_assessment_context outgoing data port
    * @param api_check_status outgoing data port
    * @param api_publication_directive outgoing data port
    */
  @strictpure def compute_CEP_T_Case (
      In_lastAdmittedToken: Battery_Status_Assessment_Service.LastAdmittedToken.Type,
      In_lifecycleState: Battery_Status_Assessment_Service.LifecycleState.Type,
      lastAdmittedToken: Battery_Status_Assessment_Service.LastAdmittedToken.Type,
      lifecycleState: Battery_Status_Assessment_Service.LifecycleState.Type,
      api_acquisition_outcome: Battery_Status_Assessment_Service.AcquisitionOutcome.Type,
      api_check_request: Battery_Status_Assessment_Service.CheckRequest,
      api_publication_outcome: Battery_Status_Assessment_Service.PublicationOutcome.Type,
      api_acquisition_directive: Battery_Status_Assessment_Service.AcquisitionDirective.Type,
      api_assessment_context: Battery_Status_Assessment_Service.AssessmentContext.Type,
      api_check_status: Battery_Status_Assessment_Service.CheckStatus.Type,
      api_publication_directive: Battery_Status_Assessment_Service.PublicationDirective.Type): B =
    {
      val r0 = compute_case_PRIOR_PUBLICATION_FAULT(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r1 = compute_case_PRIOR_ACQUISITION_FAULT(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r2 = compute_case_RESET_CONFIRMATIONS(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r3 = compute_case_RESET_IN_RECOVERY(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_check_request, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r4 = compute_case_RECOVERY_BLOCKS_NONRESET(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_check_request, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r5 = compute_case_PRIOR_CONSUMPTION_COMPLETES(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r6 = compute_case_ACTIVE_CANCEL(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_check_request, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r7 = compute_case_IDLE_DUPLICATE_TOKEN_A(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_check_request, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r8 = compute_case_IDLE_DUPLICATE_TOKEN_B(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_check_request, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r9 = compute_case_FRESH_TOKEN_A_START(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_check_request, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r10 = compute_case_FRESH_TOKEN_B_START(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_check_request, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r11 = compute_case_ACTIVE_START_BUSY(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_check_request, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r12 = compute_case_CHECK_BECOMES_AVAILABLE(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_check_request, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)
      val r13 = compute_case_ORDINARY_NONHOLD(In_lastAdmittedToken, In_lifecycleState, lastAdmittedToken, lifecycleState, api_acquisition_outcome, api_check_request, api_publication_outcome, api_acquisition_directive, api_assessment_context, api_check_status, api_publication_directive)

      r0 & r1 & r2 & r3 & r4 & r5 & r6 & r7 & r8 & r9 & r10 & r11 & r12 & r13
    }

